/* Inserted inside the original scene-block controller. Its grouped-number layout is retained. */
  var specialScope=parent.DContactPolicy.specialScope(),specialVersion=0,specialError='',specialPending=null,specialDirty=false;
  var tianrunModes=[{value:1,label:'预览外呼'},{value:2,label:'主叫外呼'},{value:4,label:'Webcall 外呼'},{value:8,label:'预测外呼'}];
  platformCatalog=[{code:'电声',name:'电声平台',available:true,codePrefix:'NISSAN'},{code:'天润',name:'天润云呼叫',available:true,providerCode:'TIANRUN'}];
  function copySpecial(value){return JSON.parse(JSON.stringify(value));}
  function blacklistCall(method,args){return escapeHtml("window.Pages['scene-block']."+method+'('+(args||[]).map(function(v){return JSON.stringify(v);}).join(',')+')');}
  function blacklistLink(label,method,args){return '<a href="#" onclick="event.preventDefault();'+blacklistCall(method,args)+'">'+escapeHtml(label)+'</a>';}
  function isTianrun(binding){return binding&&(binding.providerCode==='TIANRUN'||binding.platformCode==='天润');}
  function tianrunAccount(){var c=parent.DSession.context();return c&&c.scope.kind==='tenant'&&c.scope.tenant.modules.cloud&&c.scope.tenant.enterpriseId?String(c.scope.tenant.enterpriseId):'';}
  function canConfigureTianrun(){var c=parent.DSession.context();return !!tianrunAccount()&&!!c&&(parent.DRolePermissions?.moduleEnabled?parent.DRolePermissions.moduleEnabled('cloud',c):(c.scope.grant.modules||[]).indexOf('cloud')>=0);}
  function modeNames(mask){return tianrunModes.filter(function(m){return (Number(mask)&m.value)!==0;}).map(function(m){return m.label;}).join('、');}
  function bindingRange(b){return isTianrun(b)?(Number(b.type)===1?'呼入':modeNames(b.useRange)||'外呼范围待配置'):'沿原 AI 场景范围';}
  function shortTerm(value){var m=/^(\d+)\s*天$/.exec(value||'');return !!m&&Number(m[1])<30;}
  function rowStateLabel(row){var state=parent.DContactPolicy.specialState(row);return row._legacyRefusal&&row._legacyState==='pending'?'保存结果待核':state==='released'?'已解除':state==='expired'?'已到期':state==='removal-pending'?'解除待核':state==='expiry-pending'?'期限待核':'生效中';}
  platformByCode=function(code){return platformCatalog.find(function(p){return p.code===code;})||{code:code,name:code||'未知平台'};};
  bindingFor=function(group,code){return group&&(group.platformBindings||[]).find(function(b){return b.platformCode===code;});};
  function loadSpecialState(){try{var saved=parent.DContactPolicy.getSpecial(specialScope,{groups:groups,rows:rows});groups=saved.groups;rows=saved.rows;specialVersion=saved.version;specialError='';if(!groups.some(function(g){return g.id===activeGroupId;}))activeGroupId=groups[0]?groups[0].id:'';return true;}catch(error){specialError=error.message;return false;}}
  loadSpecialState();
  function specialAllowed(operation){if(!parent.DContactPolicy.canSpecial(specialScope,operation)){showToast('当前没有此租户黑名单的操作权限','warning');return false;}return true;}
  function normalGroup(group){if(!group)return false;if(group._legacyRefusalGroup){showToast('该分组保留既有客户拒联记录，请选择其他分组维护号码或同步设置','info');return false;}return true;}
  function specialCommit(operation,change,message,extraTarget){
    if(specialPending){try{var known=parent.DContactPolicy.reconcileSpecial(specialScope,specialPending);groups=known.groups;rows=known.rows;specialVersion=known.version;specialPending=null;specialDirty=false;activeModal=null;pendingAction=null;updatePage();showToast('本次本地保存结果已核对，各平台状态分别显示','success');return true;}catch(error){showToast(error.message,'warning');return false;}}
    if(!specialAllowed(operation)||specialError)return false;
    var target=Object.assign({groupId:operation==='group.update'?editingGroupId:pendingAction?.groupId||pendingAction?.id||activeGroupId},extraTarget||{}),next={groups:copySpecial(groups),rows:copySpecial(rows)},requestId='BL-'+Date.now()+'-'+Math.random().toString(36).slice(2,9),position=activeGroupId;
    try{var feedback=change(next);if(feedback===false)return false;var saved=parent.DContactPolicy.saveSpecial(specialScope,next,operation,specialVersion,requestId,target);groups=saved.groups;rows=saved.rows;specialVersion=saved.version;specialDirty=false;activeModal=null;pendingAction=null;editingGroupId=null;selectedPhones=[];if(!groups.some(function(g){return g.id===activeGroupId;}))activeGroupId=groups[0]?groups[0].id:'';updatePage();showToast(feedback||message||'黑名单已保存，平台同步结果待核对','success');return true;}catch(error){activeGroupId=position;if(error.message.indexOf('结果待核')>=0)specialPending=requestId;showToast(error.message,'warning');return false;}
  }
  function chosenRows(snapshot,groupId,phones){return snapshot.rows.filter(function(r){return r.groupId===groupId&&phones.indexOf(r.phone)>=0;});}
  function pendingSync(group,list,platformCode){(group.platformBindings||[]).filter(function(b){return !platformCode||b.platformCode===platformCode;}).forEach(function(b){b.status=list.length?'待核对':'待首条号码';b.lastError=list.length?'平台同步结果尚未核定':'';list.forEach(function(r){r.platformSync=r.platformSync||{};if(['expired','released'].indexOf(parent.DContactPolicy.specialState(r))<0&&!r._removalPending)r.platformSync[b.platformCode]=sync('待核对','-','平台同步结果尚未核定');});});}
  overallBindingStatus=function(group){var bindings=group.platformBindings||[];if(!bindings.length)return '仅本地';var states=bindings.map(function(b){return b.status||'待同步';});return combinedStatus(states);};
  function combinedStatus(states){var order=['解除待核','同步失败','同步异常','待核对','同步中','待同步','待首条号码'];for(var i=0;i<order.length;i++)if(states.indexOf(order[i])>=0)return order[i];return states.every(function(s){return s==='已同步';})?'已同步':'待核对';}
  overallRowStatus=function(row,group){var state=parent.DContactPolicy.specialState(row);if(state==='released')return '已解除';if(state==='expired')return parent.DContactPolicy.hasRemoteFootprint(row,group)?'到期解除待核':'已到期';if(row._removalPending)return '解除待核';if(!(group.platformBindings||[]).length)return '仅本地';return combinedStatus(group.platformBindings.map(function(b){return (row.platformSync?.[b.platformCode]||{}).status||'待同步';}));};
  refreshCounts=function(){groups.forEach(function(g){var list=rows.filter(function(r){return r.groupId===g.id;});g.count=list.length;(g.platformBindings||[]).forEach(function(b){b.recordCount=list.filter(function(r){return r.platformSync?.[b.platformCode]?.status==='已同步';}).length;});});};
  statusClass=function(status){return status==='已同步'||status==='生效中'?' success':/失败|异常/.test(status)?' error':/待|中/.test(status)?' warning':' local';};
  renderGroups=function(){var list=groups.filter(function(g){return g.name.indexOf(groupKeyword)>=0;});if(!list.length)return '<div class="block-group-empty">未找到匹配的分组</div>';return list.map(function(g){var names=enabledPlatformNames(g),actions=g._legacyRefusalGroup?'':'<span class="block-group-actions"><button title="编辑分组" onclick="event.stopPropagation();'+blacklistCall('openEditGroup',[g.id])+'">✎</button><button title="删除分组" onclick="event.stopPropagation();'+blacklistCall('requestRemoveGroup',[g.id])+'">⌫</button></span>';return '<div class="block-group-card'+(g.id===activeGroupId?' active':'')+'" onclick="'+blacklistCall('selectGroup',[g.id])+'"><div class="block-group-title-row"><span class="block-group-title">'+escapeHtml(g.name)+'</span><span class="block-group-count">('+g.count+')</span>'+actions+'</div><div class="block-group-meta">描述：'+escapeHtml(g.desc||'--')+'</div><div class="block-group-meta">有效期：'+escapeHtml(g.expire)+'</div><div class="block-group-channel">平台同步：'+escapeHtml(names.length?names.join('、'):g._legacyRefusalGroup?'沿原记录':'未启用')+' '+statusBadge(overallBindingStatus(g))+'</div></div>';}).join('');};
  renderRows=function(list){var g=currentGroup();if(!list.length)return '<tr><td colspan="10" class="block-empty">当前筛选条件下暂无黑名单号码</td></tr>';return list.map(function(r){var state=parent.DContactPolicy.specialState(r),canRetry=!r._legacyRefusal&&!r._removalPending&&['expired','released'].indexOf(state)<0&&(g.platformBindings||[]).some(function(b){return r.platformSync?.[b.platformCode]?.status!=='已同步';}),platforms=(g.platformBindings||[]).map(function(b){var s=r.platformSync?.[b.platformCode]?.status||'待同步';return '<small>'+escapeHtml(platformByCode(b.platformCode).name)+'：'+escapeHtml(s)+'</small>';}).join(''),actions=blacklistLink('详情','openRecordDetail',[r.phone]);if(state!=='released'&&!r._removalPending)actions+=' · '+blacklistLink('移除','requestRemoveNumber',[r.phone]);return '<tr><td><input type="checkbox"'+(selectedPhones.indexOf(r.phone)>=0?' checked':'')+(state==='released'?' disabled':'')+' onchange="'+blacklistCall('toggleRowSelection',[r.phone]) .replace(/\)$/g,',this.checked)')+'"></td><td>'+escapeHtml(r.phone)+'</td><td>'+escapeHtml(g.name)+'</td><td>'+escapeHtml(addTypeLabels[r.addType]||r.addType||'--')+'</td><td title="'+escapeHtml(r.reason)+'">'+escapeHtml(r.reason||'--')+'</td><td>'+escapeHtml(r.creator||r.operatorId||'--')+'</td><td>'+escapeHtml(r.createdAt||'--')+'</td><td>'+escapeHtml(r.effective||g.expire)+'<small style="display:block;color:#667085">'+escapeHtml(rowStateLabel(r))+'</small></td><td><div class="block-platform-status">'+statusBadge(overallRowStatus(r,g))+platforms+(canRetry?'<button class="block-cell-sync-btn" onclick="'+blacklistCall('retryRecord',[r.phone])+'">重试</button>':'')+'</div></td><td>'+actions+'</td></tr>';}).join('');};
  var groupedBlacklistRender=renderBlacklist;
  renderBlacklist=function(){var html=groupedBlacklistRender();return html.replace('中台统一维护黑名单，电声外呼平台由系统自动同步。','保留分组与号码管理，按本组设置分别同步到各平台。').replace('当前AI专项分组独立维护，供应商处理结果分别核对。','保留分组与号码管理，按本组设置分别同步到各平台。');};
  var sourceGroupForm=renderGroupForm;
  renderGroupForm=function(){return sourceGroupForm().replace('配置需要下发的电声平台','配置需要下发的 AI 平台或天润云呼叫');};
  renderSyncSettings=function(){var g=currentGroup();if(!g)return '';var bindings=g.platformBindings||[],body='<div class="block-modal-body"><div class="block-sync-overview"><div class="block-sync-overview-item"><span>当前分组</span><strong>'+escapeHtml(g.name)+'</strong></div><div class="block-sync-overview-item"><span>整体状态</span>'+statusBadge(overallBindingStatus(g))+'</div><div class="block-sync-overview-item"><span>已启用平台</span><strong>'+bindings.length+' 个平台</strong></div></div><div class="block-modal-section"><div class="block-section-title"><h3>已启用平台</h3><button class="btn btn-primary" onclick="'+blacklistCall('openAddPlatform')+'">添加平台</button></div><table class="block-map-table block-platform-table"><thead><tr><th>平台名称</th><th>同步目标</th><th>生效范围</th><th>同步状态</th><th>已同步号码</th><th>最近同步</th><th>操作</th></tr></thead><tbody>'+(bindings.length?bindings.map(function(b){return '<tr><td><strong>'+escapeHtml(platformByCode(b.platformCode).name)+'</strong></td><td>'+escapeHtml(isTianrun(b)?'企业 '+b.enterpriseId:b.externalGroupCode||'待生成')+'</td><td>'+escapeHtml(bindingRange(b))+'</td><td>'+statusBadge(b.status)+'</td><td>'+Number(b.recordCount||0)+' 条</td><td>'+escapeHtml(b.lastSync||'-')+'</td><td style="white-space:nowrap">'+blacklistLink('详情','openPlatformDetail',[b.platformCode])+(isTianrun(b)?' · '+blacklistLink('配置','integrationConfigurePlatform',[b.platformCode]):'')+' · '+blacklistLink('重试','retryPlatform',[b.platformCode])+' · '+blacklistLink('停用','requestDisablePlatform',[b.platformCode])+'</td></tr>';}).join(''):'<tr><td colspan="7" class="block-empty">当前分组未启用平台同步，可添加 AI 平台或天润云呼叫</td></tr>')+'</tbody></table></div><div class="block-sync-note"><strong>同步说明</strong><p>本组号码统一维护，各平台独立显示同步结果。天润按企业账号同步号码；移除或到期后，分别核对各平台的解除结果，同号其他分组的限制继续保留。</p></div></div>';return modalShell('平台同步设置',body,'<div class="block-modal-footer"><button class="btn btn-default" onclick="'+blacklistCall('closeModal')+'">关闭</button></div>','block-sync-modal','当前分组：'+g.name);};
  function storeSyncDraft(){if(!activeModal||activeModal.type!=='addPlatform')return;var direction=document.getElementById('blockTianrunDirection');if(direction)activeModal.direction=Number(direction.value);var checked=document.querySelectorAll('input[name="blockTianrunMode"]:checked');if(document.getElementById('blockTianrunRange'))activeModal.useRange=Array.from(checked).reduce(function(n,input){return n+Number(input.value);},0);}
  function selectSyncPlatform(code){storeSyncDraft();activeModal.platformCode=code;specialDirty=true;updatePage();}
  function setSyncDirection(value){activeModal.direction=Number(value);var range=document.getElementById('blockTianrunRange');if(range)range.hidden=Number(value)!==2;specialDirty=true;}
  function configurePlatform(code){if(!specialAllowed('sync.update')||!normalGroup(currentGroup()))return false;var b=bindingFor(currentGroup(),code);if(!b)return false;setModal('addPlatform',{editingPlatform:code,platformCode:code,direction:Number(b.type)||2,useRange:Number(b.useRange)||15});return true;}
  renderAddPlatform=function(){var g=currentGroup(),editing=activeModal.editingPlatform,available=editing?platformCatalog.filter(function(p){return p.code===editing;}):platformCatalog.filter(function(p){return p.available&&!bindingFor(g,p.code);}),code=activeModal.platformCode||available[0]?.code;activeModal.platformCode=code;var direction=activeModal.direction===1?1:2,mask=activeModal.useRange===undefined?15:activeModal.useRange;var cards=available.map(function(p){return '<label class="block-platform-option'+(code===p.code?' active':'')+'"><input type="radio" name="blockPlatform" value="'+p.code+'"'+(code===p.code?' checked':'')+(editing?' disabled':'')+' onchange="'+blacklistCall('integrationSelectPlatform',[p.code])+'"><span><strong>'+escapeHtml(p.name)+'</strong></span></label>';}).join('');var fields=code==='天润'?'<div class="block-form-row"><label>天润企业账号：</label><span class="block-static-value">'+escapeHtml(tianrunAccount()||'当前租户尚未绑定天润账号')+'</span></div><div class="block-form-row required"><label>呼叫方向：</label><select id="blockTianrunDirection" class="block-form-select" onchange="window.Pages[\'scene-block\'].integrationDirection(this.value)"><option value="2"'+(direction===2?' selected':'')+'>外呼</option><option value="1"'+(direction===1?' selected':'')+'>呼入</option></select></div><div id="blockTianrunRange"'+(direction!==2?' hidden':'')+'><div class="block-form-row required"><label>外呼生效范围：</label><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+tianrunModes.map(function(m){return '<label style="display:flex;align-items:center;gap:6px;width:auto"><input type="checkbox" name="blockTianrunMode" value="'+m.value+'"'+((mask&m.value)?' checked':'')+'>'+m.label+'</label>';}).join('')+'</div></div></div><div class="block-form-row"><label>有效期：</label><span class="block-static-value">'+escapeHtml(g.expire)+(shortTerm(g.expire)?' · 按本组期限由中台到期解除':'')+'</span></div>'+(!canConfigureTianrun()?'<div class="block-sync-error">当前租户需先开通云呼叫并绑定天润企业账号。</div>':''):'<div class="block-sync-note"><p>沿用原 AI 平台分组同步方式，平台处理结果单独展示。</p></div>';return modalShell(editing?'调整平台同步配置':'添加同步平台','<div class="block-modal-body"><div class="block-platform-options">'+(cards||'<div class="block-empty">当前可选平台均已启用</div>')+'</div>'+fields+'</div>','<div class="block-modal-footer"><button class="btn btn-default" onclick="'+blacklistCall('openSyncSettings')+'">返回</button>'+(available.length?'<button class="btn btn-primary"'+(code==='天润'&&!canConfigureTianrun()?' disabled':'')+' onclick="'+blacklistCall('submitAddPlatform')+'">'+(editing?'保存配置':'启用并同步')+'</button>':'')+'</div>','block-form-modal','当前分组：'+g.name);};
  renderPlatformDetail=function(){var g=currentGroup(),b=bindingFor(g,activeModal.platformCode);if(!b)return renderSyncSettings();var fields=[['中台分组',g.name],['同步平台',platformByCode(b.platformCode).name],['生效范围',bindingRange(b)],['最近同步',b.lastSync||'-']];if(isTianrun(b))fields.push(['天润企业账号',b.enterpriseId||'待绑定'],['有效期',g.expire+(shortTerm(g.expire)?'，由中台到期解除':'')]);else fields.push(['平台分组编码',b.externalGroupCode||'待生成'],['平台分组 ID',b.externalGroupId||'尚未回填'],['外部分组名称',b.externalGroupName||g.name]);var body='<div class="block-modal-body"><div class="block-sync-overview"><div class="block-sync-overview-item"><span>同步平台</span><strong>'+escapeHtml(platformByCode(b.platformCode).name)+'</strong></div><div class="block-sync-overview-item"><span>同步状态</span>'+statusBadge(b.status)+'</div><div class="block-sync-overview-item"><span>已同步号码</span><strong>'+Number(b.recordCount||0)+' 条</strong></div></div><div class="block-info-grid block-info-grid-3">'+fields.map(function(f){return '<div class="block-info-item"><span>'+f[0]+'</span><strong>'+escapeHtml(f[1])+'</strong></div>';}).join('')+'</div>'+(b.lastError?'<div class="block-sync-error"><strong>最近处理说明</strong><span>'+escapeHtml(b.lastError)+'</span></div>':'')+'<div class="block-sync-note"><strong>'+escapeHtml(platformByCode(b.platformCode).name)+'同步说明</strong><p>'+(isTianrun(b)?'本组号码同步至当前租户绑定的天润企业账号。天润不建立对应分组，分组和期限由中台保留；同号其他分组仍有效时继续保留对应限制。':'保留原平台分组编码与号码同步记录，各平台结果独立核对。')+'</p><p>当前原型仅保存本地配置，平台实际处理结果仍待核对。</p></div></div>';return modalShell(platformByCode(b.platformCode).name+'同步详情',body,'<div class="block-modal-footer"><button class="btn btn-danger-ghost" onclick="'+blacklistCall('requestDisablePlatform',[b.platformCode])+'">停用同步</button>'+(isTianrun(b)?'<button class="btn btn-default" onclick="'+blacklistCall('integrationConfigurePlatform',[b.platformCode])+'">调整配置</button>':'')+'<button class="btn btn-primary" onclick="'+blacklistCall('retryPlatform',[b.platformCode])+'">重新同步</button><button class="btn btn-default" onclick="'+blacklistCall('openSyncSettings')+'">返回</button></div>','block-sync-modal block-detail-modal','当前分组：'+g.name);};
  renderPhoneInputs=function(){return activeModal.phones.map(function(phone,index){return '<div class="block-phone-row"><input inputmode="tel" maxlength="16" value="'+escapeHtml(phone)+'" placeholder="手机号或带区号固话" oninput="window.Pages[\'scene-block\'].integrationUpdatePhone('+index+',this.value)"><button title="删除" onclick="'+blacklistCall('removePhoneInput',[index])+'">×</button></div>';}).join('')+'<a class="block-add-phone'+(activeModal.phones.length>=10?' disabled':'')+'" href="#" onclick="event.preventDefault();'+blacklistCall('addPhoneInput')+'">+ 添加号码（'+activeModal.phones.length+'/10）</a>';};
  function updateBlacklistPhone(index,value){if(activeModal&&activeModal.phones)activeModal.phones[index]=parent.DContactPolicy.normalize(value).replace(/[^0-9]/g,'').slice(0,12);specialDirty=true;}
